types.CallRequest.ts:
/** One-shot request accepted by models.call: a single user prompt to one enabled model of a stored connection. */
export type CallRequest = {
    /** Model connection UUID. */
    connectionId: string;
    /** Provider-native model id on the connection. */
    model: string;
    /** Non-empty user prompt sent as one user message. */
    user: string;
    /** Optional system instructions. */
    system?: string;
    /** Sampling temperature for providers declaring capabilities.sampling; otherwise reported in ignored. @minimum 0 @maximum 2 */
    temperature?: number;
    /** Output token budget for providers declaring capabilities.sampling; otherwise reported in ignored. @minimum 1 */
    maxTokens?: number;
    /** Reasoning preference such as auto, off, low, medium or high; normalized for providers declaring capabilities.reasoning. */
    reasoningEffort?: string;
    /** Structured output request; the returned text is compact validated JSON. */
    responseFormat?: types.models.ResponseFormat;
    /** Provider-specific options passed unchanged; unknown keys fail INVALID_INPUT in the provider. */
    providerOptions?: Record<string, unknown>;
    /** Stable correlation id reused across retries; generated once when omitted. */
    sessionId?: string;
    /** Total deadline across all attempts and retry delays. @minimum 1 @maximum 3600000 */
    timeoutMs?: number;
    /** Caller cancellation signal; combined with timeoutMs. */
    signal?: AbortSignal;
};

types.CallResult.ts:
/** Result of models.call. */
export type CallResult = {
    /** Generated text; compact JSON when responseFormat was requested. */
    text: string;
    /** Normalized finish reason such as stop, length or tool_calls; null when unknown. */
    finishReason: string | null;
    /** Token usage reported by the provider for the successful attempt. */
    usage: types.models.StreamResult["usage"];
    /** Requested and applied reasoning when the provider declares capabilities.reasoning. */
    reasoning?: types.models.ReasoningResolution;
    /** Number of attempts made, including the successful one. @minimum 1 @maximum 3 */
    attempts: number;
    /** Option names dropped because the provider does not declare the matching capability. */
    ignored: ("temperature" | "maxTokens")[];
};

types.Checkpoint.ts:
/** Serializable SDK-native compaction checkpoint. Persist verbatim and replay through a CheckpointEntry; payload is opaque and never prose. */
export type Checkpoint = {
    kind: "native-checkpoint";
    version: 1;
    /** Compatibility identity: replay is accepted only on the same provider, connection and model. */
    provider: string;
    connectionId: string;
    model: string;
    /** Provider-native opaque item. */
    payload: Record<string, unknown>;
};

types.CompactRequest.ts:
/** Provider-neutral native compaction request for models.compact and ProviderDefinition.compact. */
export type CompactRequest = {
    /** Provider-native model id on the connection. */
    model: string;
    /** Effective instructions for the compacted transcript. */
    instructions: string;
    /** Ordered transcript to compact; may contain earlier native checkpoint entries for providers declaring capabilities.checkpoints. */
    messages: (Record<string, unknown> | types.models.CheckpointEntry)[];
    /** Optional handoff guidance identifying what the compacted context should preserve. */
    focus?: string;
    /** Provider output token budget for compaction. @minimum 1 */
    maxTokens?: number;
    /** Stable session or agent id. */
    sessionId: string;
    /** Cancels the provider request. */
    signal?: AbortSignal;
};

types.CompactResult.ts:
/** Opaque provider compaction checkpoint; callers persist the item verbatim. */
export type CompactResult = {
    item: { type: "compaction"; id?: string; encrypted_content: string }
        | { type: "compaction"; content: string; signature: string };
    responseId: string;
    /** Provider stop reason for native compaction, when reported. */
    stopReason?: string;
    usage: { prompt_tokens: number; completion_tokens: number };
    /** Portable SDK checkpoint wrapping `item`, added by models.compact for providers declaring capabilities.checkpoints. Replay it as a CheckpointEntry. */
    checkpoint?: types.models.Checkpoint;
};

types.ConnectionView.ts:
/** Secret-free connection projection for clients: secret fields report only whether a value is stored. */
export type ConnectionView = {
    /** System-generated UUID. */
    id: string;
    /** Registered provider id. */
    provider: string;
    /** False when the provider declaration is no longer registered. */
    providerRegistered: boolean;
    /** Non-unique display name, 1–100 characters. */
    accountName: string;
    /** Non-secret configuration; manual model ids are stored under `models`. */
    config: types.models.ResolvedConnection["config"];
    /** Secret field key → whether a value is stored. Never values or refs. */
    secrets: Record<string, boolean>;
    transport: types.models.TransportSpec;
    enabled: boolean;
    /** Model ids the owner disabled on this connection; inference refuses them. Sorted, unique. */
    disabledModels: string[];
    /** Unix epoch milliseconds. */
    createdAt: number;
    /** Unix epoch milliseconds; changes on every update. */
    updatedAt: number;
};

types.FailureInfo.ts:
/** Credential-safe SDK failure metadata carried on errors thrown by models.stream/compact and opted-in providers. */
export type FailureInfo = {
    /** Stable error code, e.g. LOGIN_REQUIRED, QUOTA_EXHAUSTED, RATE_LIMITED, INVALID_INPUT, UNSUPPORTED, CAPABILITY_UNAVAILABLE, PROVIDER_ERROR, CANCELLED, TRANSPORT. */
    code: string;
    classification: "auth" | "quota" | "throttled" | "invalid_input" | "unsupported" | "capability_unavailable" | "provider" | "cancelled" | "transport";
    /** Upstream HTTP status, when one was received. */
    upstreamStatus?: number;
    /** Suggested wait before a caller-level retry, in milliseconds. */
    retryAfterMs?: number;
    /** Whether the provider may have accepted (and billed/executed) the request. */
    acceptance: "none" | "rejected" | "accepted" | "uncertain";
    /** Transient condition: a later attempt may succeed. Independent of replaySafe. */
    retryable: boolean;
    /** True only when automatically repeating the same request cannot duplicate provider-side work. */
    replaySafe: boolean;
};

types.FieldSpec.ts:
/** Configuration schema consumed by connection validation and schema-driven forms. */
export type FieldSpec = {
    /** Stable configuration key, unique within the provider. */
    key: string;
    /** Human-readable field name. */
    label: string;
    /** Whether a value must be supplied before saving a connection. */
    required?: boolean;
    /** Safe explanatory text; never include credentials. */
    help?: string;
    /** Safe example displayed when the field is empty. */
    placeholder?: string;
} & (
    | { type: "text" | "url"; default?: string }
    | { type: "select"; default?: string; options: { value: string; label: string }[] }
    | { type: "secret"; default?: never }
    | { type: "number"; default?: number }
    | { type: "boolean"; default?: boolean }
);

types.LoginFlow.ts:
/** Process-local provider login flow; only its public fields are ever returned. */
export type LoginFlow = {
    flowId: string;
    status: "pending" | "succeeded" | "failed" | "expired";
    /** Selects the provider's device-code or PKCE authorization-code UI. */
    kind: "device-code" | "authorization-code";
    verificationUri?: string;
    userCode?: string;
    /** Provider authorization page for authorization-code flows. */
    authorizationUrl?: string;
    /** Whether a best-effort local callback listener is running. */
    callbackListening?: boolean;
    /** Unix epoch milliseconds. */
    expiresAt: number;
    /** Safe status message, never containing tokens or codes other than the user code. */
    message?: string;
    abort: AbortController;
    /** Background poll; settles when the flow leaves pending. */
    done?: Promise<void>;
};

types.ModelInfo.ts:
/** Secret-free model descriptor returned by a provider or manual configuration. */
export type ModelInfo = {
    /** Provider-native model identifier. */
    id: string;
    label?: string;
    description?: string;
    contextWindow?: number;
    maxOutputTokens?: number;
    /** Provider-reported reasoning levels and default, when discovery supplies them. */
    reasoning?: { supported: types.models.ReasoningLevel[]; default: types.models.ReasoningLevel };
    reasoningUnavailable?: true;
    responseControls?: {
        speed?: { supported: ("standard" | "fast" | "ultrafast")[] };
        verbosity?: { supported: ("low" | "medium" | "high")[]; default?: "low" | "medium" | "high" };
    };
    /** Set by models.listModels: true when the owner disabled this model on the connection. */
    disabled?: boolean;
};

types.ProviderDefinition.ts:
/** SDK v0 backend contract for a mounted $modelProvider_<id>.ts declaration. */
export type ProviderDefinition = {
    /** Lowercase kebab-case id matching the declaration filename. */
    id: string;
    label: string;
    description?: string;
    /** Lucide icon name or data URL. */
    icon?: string;
    fields: types.models.FieldSpec[];
    transports: types.models.TransportSpec["kind"][];
    /** Test this connection only; use conn.fetch and never log conn.secret results. */
    test: (ctx: Context, conn: types.models.ResolvedConnection) => Promise<types.models.TestResult>;
    listModels?: (ctx: Context, conn: types.models.ResolvedConnection) => Promise<types.models.ModelInfo[]>;
    usage?: (ctx: Context, conn: types.models.ResolvedConnection) => Promise<types.models.UsageReport>;
    clientVersion?: (ctx: Context, conn: types.models.ResolvedConnection, opts: { refresh?: boolean }) => Promise<{ version: string; source: string; detail?: string }>;
    /** Additional provider-specific validation after core field validation. Throw to reject. */
    validate?: (ctx: Context, config: types.models.ResolvedConnection["config"]) => void | Promise<void>;
    /** Optional streaming inference; called only through models.stream after the enabled checks. Send traffic only through conn.fetch. */
    stream?: (ctx: Context, conn: types.models.ResolvedConnection, req: types.models.StreamRequest) => Promise<types.models.StreamResult>;
    /** Optional native transcript compaction; called only through models.compact after the enabled checks. */
    compact?: (ctx: Context, conn: types.models.ResolvedConnection, req: types.models.CompactRequest) => Promise<types.models.CompactResult>;
    /** Additive SDK features this provider opts into; omitted means none. */
    capabilities?: {
        /** Accepts and returns run-scoped ProviderState. */
        continuationState?: boolean;
        /** Accepts CheckpointEntry input and gets portable checkpoints wrapped around compact results. */
        checkpoints?: boolean;
        /** Receives SDK-normalized reasoning in StreamRequest.reasoning; requires model metadata or reasoningProfile. */
        reasoning?: boolean;
        /** Accepts StreamRequest.temperature and maxTokens; without it models.stream drops them. */
        sampling?: boolean;
        /** Accepts StreamRequest.responseFormat and maps it to native structured output; without it models.call uses an instruction fallback. */
        structuredOutput?: boolean;
    };
    /** Documented versioned reasoning profile used when model discovery metadata has none; return null when no profile applies to the model. */
    reasoningProfile?: (ctx: Context, model: string) => types.models.ReasoningCapabilities | null;
    actions?: Record<string, {
        label: string;
        /** Provider-owned login/logout/etc. Return only safe JSON, never credentials. */
        run: (ctx: Context, conn: types.models.ResolvedConnection, input: types.models.ActionValue) => Promise<types.models.ActionValue>;
    }>;
};

types.ProviderState.ts:
/** Opaque provider continuation state bound to one provider, connection, session and logical run. Caller-owned: carry it between requests of the same run and drop it when the run ends. Private operational data — do not log or show it. */
export type ProviderState = {
    provider: string;
    connectionId: string;
    sessionId: string;
    runId: string;
    /** Provider-private string values; opaque to callers. */
    data: Record<string, string>;
};

types.ProviderView.ts:
/** Public catalogue entry: only declarative metadata, never handlers or connection data. */
export type ProviderView = {
    id: string;
    label: string;
    description?: string;
    icon?: string;
    hasClientVersion: boolean;
    fields: types.models.FieldSpec[];
    transports: types.models.TransportSpec["kind"][];
    actions: { name: string; label: string }[];
};

types.QuotaObservation.ts:
/** Quota windows observed on an inference response; separate from token usage. */
export type QuotaObservation = {
    windows: {
        /** primary, secondary or tertiary provider window. */
        name: string;
        /** Percentage from 0 to 100. */
        usedPercent: number;
        windowMinutes?: number;
        /** Unix epoch milliseconds. */
        resetAt?: number;
    }[];
    source: "headers" | "stream";
};

types.ReasoningCapabilities.ts:
/** Validated reasoning levels one provider model supports, from discovery metadata or a documented SDK profile. */
export type ReasoningCapabilities = {
    /** Supported levels; nonempty, unique, SDK enumeration only. */
    supported: types.models.ReasoningLevel[];
    /** Level applied for an omitted or auto preference; must be one of supported. */
    default: types.models.ReasoningLevel;
    /** Where the capabilities came from: provider model discovery or a versioned SDK profile. */
    source: "metadata" | "profile";
    /** Versioned profile id when source is profile, e.g. codex-2026-07. */
    profile?: string;
};

types.ReasoningResolution.ts:
/** Requested versus applied reasoning, resolved by models.stream before inference for opted-in providers. */
export type ReasoningResolution = {
    /** Caller preference as submitted; omitted is reported as auto. Never written back to caller settings. */
    requested: types.models.ReasoningLevel | "auto";
    /** Level the provider must send. */
    applied: types.models.ReasoningLevel;
    /** Why applied differs from requested (fallback), or null. */
    fallbackReason: string | null;
    source: types.models.ReasoningCapabilities["source"];
    profile?: string;
};

types.ResolvedConnection.ts:
/** Provider-facing connection. Only this connection's secrets and bound transport are exposed. */
export type ResolvedConnection = {
    id: string;
    provider: string;
    accountName: string;
    /** Non-secret configuration only; manually configured models may be a string array. */
    config: Record<string, string | number | boolean | string[] | null>;
    /** Lazily decrypt a declared secret field; absent secrets return null. Never log the result. */
    secret: (key: string) => Promise<string | null>;
    /** Send HTTP using the connection's transport; never fall back to a direct request. */
    fetch: (url: string, init?: RequestInit) => Promise<Response>;
};

types.ResponseFormat.ts:
/** Structured output request for models.call and StreamRequest.responseFormat: any JSON object, or JSON matching a JSON Schema. */
export type ResponseFormat =
    | { type: "json_object" }
    | {
        type: "json_schema";
        /** Schema name sent to providers that require one. */
        name: string;
        /** JSON Schema of the expected value; models.call checks top-level type, required and additionalProperties:false. */
        schema: Record<string, unknown>;
        /** Ask the provider for strict schema adherence where supported. @default true */
        strict?: boolean;
    };

types.State.ts:
/** Provider registry and connection health cache owned by the models namespace. */
export type State = {
    codexDispatch?: WeakMap<object, { chat?: (route: { connectionId: string; generation: string | null; modelId: string }) => Promise<{ speed?: "fast" | "ultrafast"; verbosity?: "low" | "medium" | "high" }>; pin?: { generation?: string | null }; generation?: string | null }>;
    codexHandoff?: WeakMap<RequestInit, (send: (body: string) => void) => Promise<void>>;
    providers?: Record<string, {
        owner: string;
        module: string;
        rel: string;
        definition: types.models.ProviderDefinition;
    }>;
    /** `<connection id>:<Bun.hash(id + updated_at)>:<test|usage>` key; 60 s expiry with in-flight de-duplication. */
    health?: Record<string, {
        expiresAt: number;
        result?: types.models.UsageReport | types.models.TestResult;
        pending?: Promise<types.models.UsageReport | types.models.TestResult>;
    }>;
    /** In-flight Codex token refresh per connection id; de-duplicates concurrent refreshes. */
    codexRefresh?: Record<string, Promise<string>>;
    codexBoundRefresh?: Record<string, Promise<{ generation: string | null; credentialRevision: number; loggedIn: boolean; needsLogin: boolean; accountId: string | null; expiresAt: number | null; accessToken?: string }>>;
    /** Process-local Codex device-code login flows by connection id; lost on restart. */
    loginFlows?: Record<string, types.models.LoginFlow>;
};

types.StreamEvent.ts:
/** Normalized incremental inference event passed to StreamRequest.onEvent. */
export type StreamEvent =
    | { type: "text_delta"; delta: string }
    | { type: "thinking_delta"; delta: string; visibility: "public_summary" }
    | { type: "tool_args_delta"; delta: string; id?: string };

types.StreamRequest.ts:
/** Provider-neutral streaming inference request for models.stream and ProviderDefinition.stream. */
export type StreamRequest = {
    /** Provider-native model id on the connection. */
    model: string;
    /** Effective system instructions. */
    instructions: string;
    /** Ordered input: OpenAI-shaped chat messages (role/content/tool_calls/tool_call_id), optionally with native checkpoint entries at their history position. Checkpoint entries reach only providers declaring capabilities.checkpoints. */
    messages: (Record<string, unknown> | types.models.CheckpointEntry)[];
    /** Number of leading messages eligible for prompt caching, excluding transient guidance. @minimum 0 */
    cacheableMessageCount?: number;
    /** Wire tool schemas in the provider's API shape (Responses `function` tools for Codex). */
    tools?: Record<string, unknown>[];
    /** Reasoning preference such as auto, off, low, medium or high. Opted-in providers receive the normalized value in `reasoning`; this field keeps the caller's original value. */
    reasoningEffort?: string;
    /** Set by models.stream for providers declaring capabilities.reasoning: requested/applied reasoning resolved before inference. */
    reasoning?: types.models.ReasoningResolution;
    /** Stable session or agent id used for request correlation (and prompt caching when promptCacheKey is absent). */
    sessionId: string;
    /** Caller-chosen prompt cache identity, e.g. shared by sessions with inherited history. Falls back to sessionId. Session correlation is unaffected. */
    promptCacheKey?: string;
    /** Caller-owned logical run (turn) id. Required to submit or receive continuation state; use a new id per run. */
    runId?: string;
    /** Continuation state returned by the previous request of the same run; validated against provider, connection, session and run before any network request. */
    state?: types.models.ProviderState;
    /** Cancels the provider request. */
    signal?: AbortSignal;
    /** Sampling temperature; models.stream passes it only to providers declaring capabilities.sampling. @minimum 0 @maximum 2 */
    temperature?: number;
    /** Output token budget; models.stream passes it only to providers declaring capabilities.sampling. @minimum 1 */
    maxTokens?: number;
    /** Structured output request; models.stream passes it only to providers declaring capabilities.structuredOutput. */
    responseFormat?: types.models.ResponseFormat;
    /** Provider-specific options passed unchanged; the provider rejects keys it does not support with INVALID_INPUT. */
    providerOptions?: Record<string, unknown>;
    /** Receives incremental text, reasoning and tool-argument deltas. */
    onEvent?: (event: types.models.StreamEvent) => void;
};

types.StreamResult.ts:
/** Normalized streaming result; matches the legacy llm stream result shape plus additive SDK observations. */
export type StreamResult = {
    text: string;
    thinking: string;
    /** stop, length, tool_calls or null when unknown. */
    finishReason: string | null;
    /** Token counters only; quota lives in `quota`. */
    usage: { prompt_tokens?: number; completion_tokens?: number; cache_read_tokens?: number; cache_write_tokens?: number };
    /** Tool calls; unparseable arguments are `{ __unparsed: raw }` for downstream validation. */
    toolCalls: { id: string; name: string; args: unknown }[];
    /** Continuation state to pass with the next request of the same run (requires runId and provider support). */
    state?: types.models.ProviderState;
    /** Quota windows the provider reported on this response, without an extra request. */
    quota?: types.models.QuotaObservation;
    /** Requested/applied reasoning for providers opting into SDK normalization. */
    reasoning?: types.models.ReasoningResolution;
};

types.TestResult.ts:
/** Safe connection health result; disabled is produced by core without calling the provider. */
export type TestResult = {
    status: "available" | "unavailable" | "configured" | "disabled";
    /** Machine-readable reason such as models-ok or generation-failed. */
    reason: string;
    /** Short human-readable explanation containing no secret values or refs. */
    message: string;
    /** Unix epoch milliseconds when the check completed. */
    checkedAt: number;
};

types.TransportSpec.ts:
/** Outbound transport for one connection; proxies and SSH hosts reference saved configuration. */
export type TransportSpec =
    | { kind: "direct" }
    | { kind: "socks"; proxyId: string }
    | { kind: "ssh-tunnel"; instance: string };

types.UsageReport.ts:
/** Standard usage snapshot, or status-only fallback from a cached connection test. */
export type UsageReport = {
    status: types.models.TestResult["status"];
    reason?: string;
    /** Subscription plan reported by the provider, when available. */
    plan?: string;
    /** Unix epoch milliseconds. */
    checkedAt: number;
    windows?: {
        label: string;
        /** Percentage from 0 to 100. */
        usedPercent?: number;
        remaining?: number;
        /** Unix epoch milliseconds, when known. */
        resetAt?: number;
    }[];
    balance?: { amount: number; currency: string };
};

